<?php
namespace Delnavazan\Platform\Core\Application;
use Delnavazan\Platform\Core\Infrastructure\Repository\{LessonRepository,CourseRepository,LessonScheduleVersionRepository};
final class LessonScheduleService { public function initial(int $lesson,array $input):int{return $this->apply($lesson,$input,true);} public function reschedule(int $lesson,array $input):int{return $this->apply($lesson,$input,false);} private function apply(int $id,array $in,bool $initial):int{if(!current_user_can('dzn_manage_lessons'))throw new \RuntimeException('Unauthorized');$lesson=(new LessonRepository)->usable($id);if(!$lesson||in_array($lesson->status,['archived','completed','cancelled'],true))throw new \InvalidArgumentException('Lesson not schedulable');$repo=new LessonScheduleVersionRepository;$current=$repo->current($id);if(($current&&(int)$lesson->current_schedule_version_id!==(int)$current->id)||(!$current&&$lesson->current_schedule_version_id))throw new \RuntimeException('Inconsistent current schedule pointer');if($initial&&$current)throw new \InvalidArgumentException('Schedule already exists');if(!$initial&&!$current)throw new \RuntimeException('Missing current schedule');[$start,$end,$tz,$date,$time]=$this->times($lesson,$in);if($current&&$current->starts_at_utc===$start&&$current->ends_at_utc===$end&&$current->schedule_timezone===$tz&&$current->local_wall_date===$date&&$current->local_wall_time===$time)throw new \InvalidArgumentException('Schedule unchanged');$repo->begin();try{$locked=(new LessonRepository)->locked($id);if(!$locked||$locked->archived_at||in_array($locked->status,['archived','completed','cancelled'],true))throw new \InvalidArgumentException('Lesson not schedulable');$current=$repo->current($id,true);if(($current&&(int)$locked->current_schedule_version_id!==(int)$current->id)||(!$current&&$locked->current_schedule_version_id))throw new \RuntimeException('Inconsistent current schedule pointer');if($initial&&$current)throw new \InvalidArgumentException('Schedule already exists');if(!$initial&&!$current)throw new \RuntimeException('Missing current schedule');if($current&&$current->starts_at_utc===$start&&$current->ends_at_utc===$end&&$current->schedule_timezone===$tz&&$current->local_wall_date===$date&&$current->local_wall_time===$time)throw new \InvalidArgumentException('Schedule unchanged');$now=gmdate('Y-m-d H:i:s');if($current)$repo->supersede((int)$current->id,$now);$version=$repo->latest($id)+1;$sid=$repo->insert(['lesson_id'=>$id,'version_number'=>$version,'starts_at_utc'=>$start,'ends_at_utc'=>$end,'schedule_timezone'=>$tz,'local_wall_date'=>$date,'local_wall_time'=>$time,'reason'=>Normalizer::text($in['reason']??null,255),'changed_by'=>get_current_user_id()?:null,'created_at'=>$now]);(new LessonRepository)->setCurrentSchedule($id,$locked->current_schedule_version_id,$sid,$now,get_current_user_id()?:null);$repo->commit();return $sid;}catch(\Throwable $e){$repo->rollback();throw $e;}} private function times(object $lesson,array $in):array{$tz=Normalizer::timezone($in['schedule_timezone']??null);$date=(string)($in['local_wall_date']??'');$time=Normalizer::time($in['local_wall_time']??null);$zone=new \DateTimeZone($tz);$local=\DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$date.' '.$time,$zone);if(!$local||$local->format('Y-m-d H:i:s')!==$date.' '.$time)throw new \InvalidArgumentException('Invalid or nonexistent local time');$offsets=[];foreach($zone->getTransitions($local->getTimestamp()-86400,$local->getTimestamp()+86400)as$transition){$candidate=(new \DateTimeImmutable('@'.(strtotime($date.' '.$time.' UTC')-(int)$transition['offset'])))->setTimezone($zone);if($candidate->format('Y-m-d H:i:s')===$date.' '.$time)$offsets[(int)$transition['offset']]=true;}if(count($offsets)>1)throw new \InvalidArgumentException('Ambiguous local time');$course=(new CourseRepository)->usable((int)$lesson->course_id);if(!$course)throw new \RuntimeException('Lesson Course unavailable');$end=$local->modify('+'.(int)$course->default_duration_minutes.' minutes');if($end<=$local)throw new \InvalidArgumentException('Schedule end must be after start');return[$local->setTimezone(new \DateTimeZone('UTC'))->format('Y-